-- SQLite/Cloudflare D1 baseline, NOT interchangeable with PostgreSQL.
-- D1 has no PostgreSQL RLS: every query and write MUST have server-verified tenant_id predicate.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,deployment_mode TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_users(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),email TEXT,mobile TEXT,display_name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','active','suspended','deactivated')),locale TEXT NOT NULL DEFAULT 'en',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(tenant_id,email),UNIQUE(tenant_id,mobile),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS roles(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),code TEXT NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,UNIQUE(tenant_id,code),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS role_permissions(tenant_id TEXT NOT NULL REFERENCES tenants(id),role_id TEXT NOT NULL,feature_code TEXT NOT NULL,action TEXT NOT NULL,PRIMARY KEY(tenant_id,role_id,feature_code,action),FOREIGN KEY(tenant_id,role_id) REFERENCES roles(tenant_id,id));
CREATE TABLE IF NOT EXISTS user_role_assignments(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL,role_id TEXT NOT NULL,function_code TEXT NOT NULL DEFAULT '*',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(tenant_id,user_id,role_id,function_code),FOREIGN KEY(tenant_id,user_id) REFERENCES app_users(tenant_id,id),FOREIGN KEY(tenant_id,role_id) REFERENCES roles(tenant_id,id));
CREATE TABLE IF NOT EXISTS geography_nodes(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),parent_id TEXT,level TEXT NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,parent_id) REFERENCES geography_nodes(tenant_id,id));
CREATE TABLE IF NOT EXISTS user_geography_scopes(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL,geography_id TEXT NOT NULL,function_code TEXT NOT NULL DEFAULT '*',active INTEGER NOT NULL DEFAULT 1,UNIQUE(tenant_id,user_id,geography_id,function_code),FOREIGN KEY(tenant_id,user_id) REFERENCES app_users(tenant_id,id),FOREIGN KEY(tenant_id,geography_id) REFERENCES geography_nodes(tenant_id,id));
CREATE TABLE IF NOT EXISTS approval_requests(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,maker_id TEXT NOT NULL REFERENCES app_users(id),reviewer_id TEXT REFERENCES app_users(id),status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,payload_json TEXT NOT NULL DEFAULT '{}',submitted_at TEXT NOT NULL,reviewed_at TEXT,CHECK(reviewer_id IS NULL OR reviewer_id<>maker_id));
CREATE TABLE IF NOT EXISTS notification_templates(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),code TEXT NOT NULL,channel TEXT NOT NULL,locale TEXT NOT NULL DEFAULT 'en',body TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,UNIQUE(tenant_id,code,channel,locale));
CREATE TABLE IF NOT EXISTS notification_preferences(tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL REFERENCES app_users(id),channel TEXT NOT NULL,consent INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,user_id,channel));
CREATE TABLE IF NOT EXISTS notification_outbox(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL REFERENCES app_users(id),channel TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT,provider_ref TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS survey_forms(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',current_version INTEGER NOT NULL DEFAULT 1,opens_at TEXT,closes_at TEXT,require_location INTEGER NOT NULL DEFAULT 0,submission_mode TEXT NOT NULL DEFAULT 'once');
CREATE TABLE IF NOT EXISTS survey_form_versions(form_id TEXT NOT NULL REFERENCES survey_forms(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),version INTEGER NOT NULL,definition_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(form_id,version));
CREATE TABLE IF NOT EXISTS survey_targets(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),form_id TEXT NOT NULL REFERENCES survey_forms(id),target_type TEXT NOT NULL,target_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS survey_submissions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),form_id TEXT NOT NULL REFERENCES survey_forms(id),form_version INTEGER NOT NULL,actor_id TEXT NOT NULL REFERENCES app_users(id),geography_id TEXT REFERENCES geography_nodes(id),answers_json TEXT NOT NULL,latitude REAL,longitude REAL,accuracy_m REAL,captured_at TEXT,location_mocked INTEGER,submitted_at TEXT NOT NULL,CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90),CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS cms_items(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),author_id TEXT NOT NULL REFERENCES app_users(id),category TEXT NOT NULL,locale TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',version INTEGER NOT NULL DEFAULT 1,payload_json TEXT NOT NULL DEFAULT '{}',approved_by TEXT REFERENCES app_users(id),published_at TEXT);
CREATE TABLE IF NOT EXISTS report_definitions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),code TEXT NOT NULL,name TEXT NOT NULL,definition_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),actor_id TEXT,action TEXT NOT NULL,resource TEXT NOT NULL,resource_id TEXT,outcome TEXT NOT NULL,correlation_id TEXT NOT NULL,metadata_json TEXT NOT NULL DEFAULT '{}',latitude REAL,longitude REAL,occurred_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feature_flags(tenant_id TEXT NOT NULL REFERENCES tenants(id),code TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,code));
CREATE TABLE IF NOT EXISTS app_releases(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),platform TEXT NOT NULL,version_name TEXT NOT NULL,version_code INTEGER NOT NULL,url TEXT NOT NULL,sha256 TEXT NOT NULL,mandatory INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,UNIQUE(tenant_id,platform,version_code));
CREATE TABLE IF NOT EXISTS commerce_rules(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),kind TEXT NOT NULL,scope TEXT NOT NULL,target_id TEXT,config_json TEXT NOT NULL,priority INTEGER NOT NULL DEFAULT 0,valid_from TEXT,valid_to TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS payment_webhook_events(tenant_id TEXT NOT NULL REFERENCES tenants(id),provider TEXT NOT NULL,event_id TEXT NOT NULL,status TEXT NOT NULL,received_at TEXT NOT NULL,PRIMARY KEY(tenant_id,provider,event_id));
CREATE INDEX IF NOT EXISTS idx_app_users_tenant_status ON app_users(tenant_id,status);
CREATE INDEX IF NOT EXISTS idx_assignments_user_active ON user_role_assignments(tenant_id,user_id,active);
CREATE INDEX IF NOT EXISTS idx_geo_parent ON geography_nodes(tenant_id,parent_id);
CREATE INDEX IF NOT EXISTS idx_scope_user ON user_geography_scopes(tenant_id,user_id,active);
CREATE INDEX IF NOT EXISTS idx_approvals_pending ON approval_requests(tenant_id,status,submitted_at);
CREATE INDEX IF NOT EXISTS idx_outbox_claim ON notification_outbox(tenant_id,status,next_attempt_at);
CREATE INDEX IF NOT EXISTS idx_survey_actor ON survey_submissions(tenant_id,actor_id,form_id);
CREATE INDEX IF NOT EXISTS idx_cms_published ON cms_items(tenant_id,status,locale,category);
CREATE INDEX IF NOT EXISTS idx_audit_tenant_time ON audit_events(tenant_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_rules_tenant_scope ON commerce_rules(tenant_id,kind,scope,active);
